import json
from collections import Counter
from dataclasses import dataclass
from datetime import datetime, timezone


@dataclass(frozen=True)
class Event:
    ts: datetime
    service: str
    level: str
    msg: str = ""


def parse_line(line):
    raw = json.loads(line)
    ts = datetime.fromisoformat(raw["ts"])
    if ts.tzinfo is None:
        # Legacy collectors write naive timestamps, which are UTC.
        ts = ts.replace(tzinfo=timezone.utc)
    return Event(
        ts=ts,
        service=raw["service"],
        level=raw["level"],
        msg=raw.get("msg", ""),
    )


def read_events(path):
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            if line.strip():
                yield parse_line(line)


def since(events, start):
    """Yield events at or after `start` (an aware datetime), compared by instant."""
    for event in events:
        if event.ts >= start:
            yield event


def count_events(events):
    return Counter((event.service, event.level) for event in events)
