import argparse
import sys
from datetime import date, datetime, time, timezone

from .events import count_events, read_events, since


def parse_day(text):
    """Parse YYYY-MM-DD into midnight UTC at the start of that day."""
    try:
        day = date.fromisoformat(text)
    except ValueError:
        raise argparse.ArgumentTypeError(
            f"invalid date {text!r}: expected YYYY-MM-DD, for example 2024-03-10"
        ) from None
    return datetime.combine(day, time.min, tzinfo=timezone.utc)


def build_parser():
    parser = argparse.ArgumentParser(prog="evlog")
    commands = parser.add_subparsers(dest="command", required=True)
    report = commands.add_parser("report", help="count events per service and level")
    report.add_argument("path", help="events file (JSON lines)")
    report.add_argument(
        "--since",
        type=parse_day,
        metavar="YYYY-MM-DD",
        help="only count events at or after the start of this day (UTC)",
    )
    return parser


def render(counts):
    lines = [f"{service} {level} {n}" for (service, level), n in sorted(counts.items())]
    lines.append(f"total {sum(counts.values())}")
    return "\n".join(lines)


def main(argv=None, out=None, err=None):
    out = out or sys.stdout
    err = err or sys.stderr
    args = build_parser().parse_args(argv)
    if args.command == "report":
        events = read_events(args.path)
        if args.since is not None:
            events = since(events, args.since)
        try:
            counts = count_events(events)
        except OSError as exc:
            print(f"evlog: cannot read {args.path!r}: {exc.strerror}", file=err)
            return 1
        print(render(counts), file=out)
    return 0
